import {products,accessories,byId,compatibility} from './catalog-data.js';
import {storageNeeds,cabinetFacts,accessoryFacts,bundlePromotions} from './solution-data.js';
export {storageNeeds,brandClaims,cabinetFacts,accessoryFacts} from './solution-data.js';
export function accessoryMatch(c,a,facts=accessoryFacts,cabinetData=cabinetFacts){const p=byId(c.product),rule=facts[a?.id]||{};if(!p||!a||rule.available===false||cabinetData[c.product]?.verifiedIncludedAccessoryIds?.includes(a.id))return false;if(!p.widths.includes(Number(c.width))||!p.depths.includes(Number(c.depth))||!p.heights.includes(Number(c.height)))return false;if(rule.cabinetSkus&&!rule.cabinetSkus.includes(p.id))return false;if(!compatibility(p,Number(c.width),a).ok)return false;const clearance=rule.internalClearance;if(clearance){if(!c.internalClearance)return false;for(const k of ['width','depth','height'])if(clearance[k]&&!(Number(c.internalClearance[k])>=clearance[k]))return false;}return true;}
export function recommend(c,needs=[],facts=accessoryFacts){if(needs.includes('basic'))return [];return storageNeeds.filter(n=>needs.includes(n.id)).map(n=>({need:n,accessory:accessories.find(a=>a.id===n.accessory)})).filter(r=>accessoryMatch(c,r.accessory,facts)).slice(0,3);}
export function compatibleAccessories(c){return accessories.filter(a=>accessoryMatch(c,a));}
const price=p=>p?.verified===true&&Number.isSafeInteger(p.amountCents)&&p.amountCents>=0?p.amountCents:null;
// Totals derive from product data, never from amounts persisted in a customer configuration.
export function priceProject(cabinets=[],standalone=[],{cabinetData=cabinetFacts,accessoryData=accessoryFacts,promotions=bundlePromotions,now=Date.now()}={}){
 let cabinetSubtotal=0,accessorySubtotal=0,discount=0,cabinetKnown=true,accessoryKnown=true;const lines=[],used=new Map(),promotionUsed=new Map();
 for(const c of cabinets){const qty=Number(c.quantity);if(!Number.isInteger(qty)||qty<1||qty>99||!byId(c.product))throw Error('Invalid cabinet quantity or SKU');const value=price(cabinetData[c.product]?.pricing);if(value===null)cabinetKnown=false;else cabinetSubtotal+=value*qty;
 for(const id of new Set(c.accessories||[])){const a=accessories.find(a=>a.id===id);if(!accessoryMatch(c,a,accessoryData,cabinetData))throw Error('Incompatible accessory');const regular=price(accessoryData[id]?.pricing);if(regular===null)accessoryKnown=false;else accessorySubtotal+=regular*qty;lines.push({c,id,qty,regular});}}
 for(const s of standalone){if(!accessories.some(a=>a.id===s.accessory)||accessoryData[s.accessory]?.available===false||accessoryData[s.accessory]?.standaloneRequest===false||!Number.isInteger(s.quantity)||s.quantity<1||s.quantity>99)throw Error('Invalid standalone accessory');const value=price(accessoryData[s.accessory]?.pricing);if(value===null)accessoryKnown=false;else accessorySubtotal+=value*s.quantity;}
 for(const line of lines){if(line.regular===null)continue;for(const rule of promotions){if(rule.verified!==true||!rule.id||!rule.cabinetSkus?.includes(line.c.product)||!rule.accessorySkus?.includes(line.id)||!['percent','fixed'].includes(rule.type)||!Number.isFinite(rule.value)||rule.value<=0)continue;if(rule.start&&(!Number.isFinite(Date.parse(rule.start))||now<Date.parse(rule.start)))continue;if(rule.end&&(!Number.isFinite(Date.parse(rule.end))||now>Date.parse(rule.end)))continue;const eligible=cabinets.filter(c=>rule.cabinetSkus.includes(c.product)).reduce((n,c)=>n+Number(c.quantity),0);if(eligible<(rule.minQuantity||1))continue;const capacity=Math.min(eligible*(rule.perCabinet||1),rule.maxEligibleQuantity??Infinity);const count=Math.min(line.qty,Math.max(0,capacity-(promotionUsed.get(rule.id)||0)));const key=lines.indexOf(line);if(!count||used.has(key))continue;const per=Math.min(line.regular,rule.type==='percent'?Math.round(line.regular*Math.min(rule.value,100)/100):Math.round(rule.value));discount+=per*count;used.set(key,true);promotionUsed.set(rule.id,(promotionUsed.get(rule.id)||0)+count);}}
 return {cabinetSubtotal:cabinetKnown?cabinetSubtotal:null,accessorySubtotal:accessoryKnown?accessorySubtotal:null,bundleDiscount:discount,total:cabinetKnown&&accessoryKnown?cabinetSubtotal+accessorySubtotal-discount:null,applied:[...promotionUsed.keys()],services:null};
}
